import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String x = next(), y = next();
        int m = y.length();
        int[] dp = new int[m + 1]; // dp[j]: longest piece of y ending at y[j-1]
        for (int i = 0; i < x.length(); i++) {
            char c = x.charAt(i);
            for (int j = m; j >= 1; j--)
                if (c == y.charAt(j - 1)) dp[j] = Math.max(dp[j], dp[j - 1] + 1);
        }
        int best = 0;
        for (int v : dp) best = Math.max(best, v);
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	x, y := nextToken(), nextToken()
	m := len(y)
	dp := make([]int, m+1) // dp[j]: longest piece of y ending at y[j-1]
	for i := 0; i < len(x); i++ {
		c := x[i]
		for j := m; j >= 1; j-- {
			if c == y[j-1] {
				dp[j] = max(dp[j], dp[j-1]+1)
			}
		}
	}
	fmt.Println(slices.Max(dp))
}
